# 注意：以下为伪代码示意，不可直接运行

class WeatherMCPServer:
    def list_prompts(self):
        # ▸ 返回所有可用的 Prompts
        return [
            {
                "name": "daily_weather_summary",
                "description": "生成指定城市的每日天气摘要",
                "arguments": [
                    {
                        "name": "city",
                        "description": "城市名称",
                        "required": True
                    },
                    {
                        "name": "date",
                        "description": "日期（默认今天）",
                        "required": False
                    }
                ]
            },
            {
                "name": "weather_travel_advice",
                "description": "基于天气给出旅行建议",
                "arguments": [
                    {
                        "name": "city",
                        "description": "目的地城市",
                        "required": True
                    },
                    {
                        "name": "days",
                        "description": "旅行天数",
                        "required": True
                    }
                ]
            }
        ]

    def get_prompt(self, name, arguments):
        # ▸ 生成具体的 Prompt 内容
        if name == "daily_weather_summary":
            city = arguments["city"]
            date = arguments.get("date", "今天")

            return {
                "messages": [
                    {
                        "role": "user",
                        "content": f"""
请为{city}生成{date}的天气摘要报告，包括：
1. 温度范围和体感温度
2. 天气状况（晴/雨/阴等）
3. 空气质量指数
4. 出行建议（是否需要带伞、注意防晒等）

请使用温暖友好的语气，就像天气预报员一样。
                        """
                    }
                ]
            }

        elif name == "weather_travel_advice":
            city = arguments["city"]
            days = arguments["days"]

            return {
                "messages": [
                    {
                        "role": "user",
                        "content": f"""
我计划去{city}旅行{days}天。
请根据未来{days}天的天气预报，给我以下建议：
1. 最佳出行时间段
2. 需要准备的衣物和装备
3. 天气可能影响的活动安排
4. 特别需要注意的事项

请结合天气数据给出具体、实用的建议。
                        """
                    }
                ]
            }

